// ===== Ohana Nov 18: Mexican Train real rules (mx:2) =====
DOMINO_MODES.mexican1={label:"Quick Mexican Train",maxPip:12,hand:15};
function dominoMxDeal(n){return n<=4?15:n<=6?12:10;}
function dominoMxPips(t){return t.a===0&&t.b===0?50:dominoPips(t);}
function dominoMxRound(players,seed,round,rounds,keep){
 const pip=12-(round-1),deck=shuffle(dominoTiles(12),rng(seed+round*7919));
 const at=deck.findIndex(t=>t.a===pip&&t.b===pip),engine=deck.splice(at,1)[0];
 const size=Math.min(dominoMxDeal(players.length),Math.floor((deck.length-8)/players.length));
 const hands=Object.fromEntries(players.map(p=>[p,deck.splice(0,size).sort((a,b)=>dominoPips(b)-dominoPips(a))]));
 const trains={};for(const p of players)trains[String(p)]={tiles:[],end:pip,start:pip,open:false};trains.mexican={tiles:[],end:pip,start:pip,open:true};
 const first=(round-1)%players.length;
 const st={mode:"mexican",mx:2,modeLabel:rounds>1?"Mexican Train":"Quick Mexican Train",maxPip:12,seed,round,rounds,engine:pip,trains,board:[{p:null,tile:engine,side:"start"}],ends:{left:pip,right:pip},hands,boneyard:deck,
  scores:keep?.scores||Object.fromEntries(players.map(p=>[p,0])),nextTurn:first,drawn:false,pendingDouble:null,
  history:(keep?.history||[]).slice(-150),lastRound:keep?.lastRound||null,roundLog:keep?.roundLog||[],
  lastPlay:{tile:engine,note:rounds>1?"Round "+round+" of "+rounds+" · "+pip+"|"+pip+" engine":pip+"|"+pip+" engine"}};
 st.history.push({p:null,tile:engine,note:"Round "+round+" starts with the "+pip+"|"+pip+" engine"});
 return st;
}
function dominoMxInit(players,seed,rounds){return dominoMxRound(players,Number(seed)||1,1,rounds,null);}
function dominoMxTargets(st,player){
 if(st.pendingDouble&&st.trains[st.pendingDouble])return [st.pendingDouble];
 return Object.keys(st.trains).filter(id=>id===String(player)||id==="mexican"||st.trains[id].open);
}
function dominoMxPlayable(st,player){
 const targets=dominoMxTargets(st,player);
 return (st.hands[player]||[]).flatMap(tile=>targets.filter(id=>{const e=st.trains[id].end;return tile.a===e||tile.b===e;}).map(id=>({tile,side:"train-"+id})));
}
function dominoMxEndRound(st,players,wentOut){
 const left={};for(const p of players){left[p]=(st.hands[p]||[]).reduce((n,t)=>n+dominoMxPips(t),0);st.scores[p]=Number(st.scores[p]||0)+left[p];}
 const summary={round:st.round,engine:st.engine,wentOut:wentOut??null,left};
 st.lastRound=summary;st.roundLog=[...(st.roundLog||[]),summary];
 st.history.push({p:wentOut??null,note:wentOut!=null?"went out and won round "+st.round:"round "+st.round+" blocked"});
 if(st.round<st.rounds){
  const next=dominoMxRound(players,st.seed,st.round+1,st.rounds,st);
  next.lastPlay={p:wentOut??null,tile:next.board[0].tile,note:(wentOut!=null?"went out · ":"Blocked · ")+"Round "+next.round+" of "+next.rounds+" starts with "+next.engine+"|"+next.engine};
  for(const k of Object.keys(st))delete st[k];Object.assign(st,next);
  return {over:false,next:st.nextTurn};
 }
 const low=Math.min(...players.map(p=>st.scores[p])),best=players.filter(p=>st.scores[p]===low),winner=best.length===1?best[0]:"tie";
 st.roundWinner=winner;st.gameOver=true;
 return {over:true,winner,next:winner==="tie"?0:players.indexOf(winner)};
}
function dominoMxMove(st,players,turn,move){
 if(st.gameOver)throw new Error("This game is finished.");
 const p=players[turn],hand=st.hands[p]||(st.hands[p]=[]),legal=dominoMxPlayable(st,p);
 if(move.action==="draw"){
  if(legal.length)throw new Error("Play a matching tile.");
  if(st.drawn)throw new Error("One draw per turn; play or pass.");
  if(!st.boneyard.length)throw new Error("No tiles left.");
  const tile=st.boneyard.shift();hand.push(tile);st.drawn=true;st.lastPlay={p,tile,note:"drew a tile"};st.history.push({p,note:"drew from the boneyard"});
  return {over:false,next:turn};
 }
 if(move.action==="pass"){
  if(legal.length)throw new Error("Play a matching tile.");
  if(st.boneyard.length&&!st.drawn)throw new Error("Draw once before passing.");
  st.trains[String(p)].open=true;st.drawn=false;
  const note=st.pendingDouble?"could not cover the double · train open":"passed · train open";
  st.lastPlay={p,note};st.history.push({p,note});
  if(!st.boneyard.length&&!players.some(who=>dominoMxPlayable(st,who).length))return dominoMxEndRound(st,players,null);
  return {over:false,next:(turn+1)%players.length};
 }
 if(move.action!=="play")throw new Error("Choose a domino move.");
 const found=legal.find(x=>x.tile.id===Number(move.tileId)&&x.side===move.side);
 if(!found)throw new Error(st.pendingDouble?"Cover the double first.":"That train is not open to you.");
 const id=move.side.slice(6),train=st.trains[id],tile=found.tile;
 hand.splice(hand.findIndex(t=>t.id===tile.id),1);
 const oriented=tile.a===train.end?tile:{...tile,a:tile.b,b:tile.a};
 train.tiles.push({p,tile:oriented,side:move.side});train.end=oriented.b;st.drawn=false;
 if(id===String(p))train.open=false;
 const isDouble=tile.a===tile.b;st.pendingDouble=isDouble?id:null;
 const where=id==="mexican"?"the Mexican train":id===String(p)?"their own train":"an open train";
 const note="played "+tile.a+"|"+tile.b+" on "+where+(isDouble?" · double, cover it":"");
 st.lastPlay={p,tile,side:move.side,note};st.history.push({p,tile,side:move.side,note});
 if(st.history.length>220)st.history=st.history.slice(-200);
 if(!hand.length)return dominoMxEndRound(st,players,p);
 return {over:false,next:isDouble?turn:(turn+1)%players.length};
}
function dominoInit2(players,seed,mode){
 if(mode==="mexican"||mode==="mexican1")return dominoMxInit(players,seed,mode==="mexican1"?1:13);
 return dominoInit1(players,seed,mode);
}
function dominoPlayable2(st,player){return st&&st.mx?dominoMxPlayable(st,player):dominoPlayable1(st,player);}
function dominoMove2(st,players,turnIdx,move){return st&&st.mx?dominoMxMove(st,players,turnIdx,move):dominoMove1(st,players,turnIdx,move);}

// ===== Ohana Nov 18: Bergen (double-six, ends that match score, first to 15) =====
DOMINO_MODES.bergen={label:"Bergen",maxPip:6,hand:6};
function dominoBgHand(players,seed,hand,keep){
 const deck=shuffle(dominoTiles(6),rng(seed+hand*104729));
 const size=Math.min(6,Math.floor((deck.length-4)/players.length));
 const hands=Object.fromEntries(players.map(p=>[p,deck.splice(0,size).sort((a,b)=>dominoPips(b)-dominoPips(a))]));
 let sp=null,si=-1,best=null;
 for(const p of players)hands[p].forEach((t,i)=>{const d=t.a===t.b,bd=best&&best.a===best.b;
  if(!best||(d&&!bd)||(d&&bd&&t.a<best.a)||(!d&&!bd&&dominoPips(t)<dominoPips(best))){best=t;sp=p;si=i;}});
 hands[sp].splice(si,1);
 const scores=keep?.scores||Object.fromEntries(players.map(p=>[p,0]));
 const gained=best.a===best.b?2:0;scores[sp]=Number(scores[sp]||0)+gained;
 const note=(hand>1?"Hand "+hand+" · ":"")+"led "+best.a+"|"+best.b+(gained?" · double header +2":"");
 const st={mode:"bergen",bergen:1,modeLabel:"Bergen",maxPip:6,seed,round:hand,target:15,board:[{p:sp,tile:best,side:"start"}],ends:{left:best.a,right:best.b},hands,boneyard:deck,scores,
  startedBy:sp,nextTurn:(players.indexOf(sp)+1)%players.length,lastHand:keep?.lastHand||null,
  lastPlay:{p:sp,tile:best,note,score:gained},history:[...(keep?.history||[]).slice(-150),{p:sp,tile:best,score:gained,note}]};
 return st;
}
function dominoBgInit(players,seed){return dominoBgHand(players,Number(seed)||1,1,null);}
function dominoBgPlayable(st,player){
 const hand=st.hands[player]||[];
 return hand.flatMap(tile=>{const s=[];if(tile.a===st.ends.left||tile.b===st.ends.left)s.push({tile,side:"left"});if(st.ends.right!==st.ends.left&&(tile.a===st.ends.right||tile.b===st.ends.right))s.push({tile,side:"right"});else if(st.ends.right===st.ends.left&&(tile.a===st.ends.right||tile.b===st.ends.right))s.push({tile,side:"right"});return s;});
}
function dominoBgEndHand(st,players,wentOut){
 let winner=wentOut;
 if(winner==null){const pips=Object.fromEntries(players.map(p=>[p,(st.hands[p]||[]).reduce((n,t)=>n+dominoPips(t),0)]));const low=Math.min(...players.map(p=>pips[p])),best=players.filter(p=>pips[p]===low);winner=best.length===1?best[0]:null;}
 if(winner!=null)st.scores[winner]=Number(st.scores[winner]||0)+1;
 st.lastHand={hand:st.round,winner,wentOut:wentOut!=null};
 st.history.push({p:winner,note:winner==null?"hand "+st.round+" blocked, tied":(wentOut!=null?"went out":"won the blocked hand")+" · +1"});
 const top=Math.max(...players.map(p=>Number(st.scores[p]||0)));
 if(top>=Number(st.target||15)){
  const lead=players.filter(p=>Number(st.scores[p]||0)===top),w=lead.length===1?lead[0]:"tie";
  st.roundWinner=w;st.gameOver=true;return {over:true,winner:w,next:w==="tie"?0:players.indexOf(w)};
 }
 const next=dominoBgHand(players,st.seed,st.round+1,st);
 next.lastPlay={...next.lastPlay,note:(winner==null?"Blocked hand · ":"")+next.lastPlay.note};
 for(const k of Object.keys(st))delete st[k];Object.assign(st,next);
 return {over:false,next:st.nextTurn};
}
function dominoBgMove(st,players,turn,move){
 if(st.gameOver)throw new Error("This game is finished.");
 const p=players[turn],hand=st.hands[p]||(st.hands[p]=[]),legal=dominoBgPlayable(st,p);
 if(move.action==="draw"){
  if(legal.length)throw new Error("You have a playable tile.");
  if(!st.boneyard.length)throw new Error("No tiles left to draw.");
  const tile=st.boneyard.shift();hand.push(tile);hand.sort((a,b)=>dominoPips(b)-dominoPips(a));
  st.lastPlay={p,tile,note:"drew a tile"};st.history.push({p,note:"drew from the boneyard"});return {over:false,next:turn};
 }
 if(move.action==="pass"){
  if(legal.length)throw new Error("You have a playable tile.");
  if(st.boneyard.length)throw new Error("Draw before passing.");
  st.lastPlay={p,note:"passed"};st.history.push({p,note:"passed"});
  if(!players.some(who=>dominoBgPlayable(st,who).length))return dominoBgEndHand(st,players,null);
  return {over:false,next:(turn+1)%players.length};
 }
 if(move.action!=="play")throw new Error("Choose a domino move.");
 const side=move.side==="left"?"left":"right",found=legal.find(x=>x.tile.id===Number(move.tileId)&&x.side===side);
 if(!found)throw new Error("That tile does not match the open end.");
 const tile=found.tile,end=st.ends[side];hand.splice(hand.findIndex(t=>t.id===tile.id),1);
 const open=tile.a===end?tile.b:tile.a;
 if(side==="left"){st.ends.left=open;st.board.unshift({p,tile,side});}else{st.ends.right=open;st.board.push({p,tile,side});}
 let gained=0,kind="";
 if(st.ends.left===st.ends.right){
  const L=st.board[0].tile,R=st.board[st.board.length-1].tile;
  if((L.a===L.b&&L.a===st.ends.left)||(R.a===R.b&&R.a===st.ends.right)){gained=3;kind="triple header";}else{gained=2;kind="double header";}
  st.scores[p]=Number(st.scores[p]||0)+gained;
 }
 const note="played "+tile.a+"|"+tile.b+" "+side+(gained?" · "+kind+" +"+gained:"");
 st.lastPlay={p,tile,side,score:gained,note};st.history.push({p,tile,side,score:gained,note});
 if(st.history.length>220)st.history=st.history.slice(-200);
 const top=Math.max(...players.map(x=>Number(st.scores[x]||0)));
 if(top>=Number(st.target||15)){const lead=players.filter(x=>Number(st.scores[x]||0)===top),w=lead.length===1?lead[0]:"tie";st.roundWinner=w;st.gameOver=true;return {over:true,winner:w,next:w==="tie"?0:players.indexOf(w)};}
 if(!hand.length)return dominoBgEndHand(st,players,p);
 return {over:false,next:(turn+1)%players.length};
}
function dominoInit(players,seed,mode){return mode==="bergen"?dominoBgInit(players,seed):dominoInit2(players,seed,mode);}
function dominoPlayable(st,player){return st&&st.bergen?dominoBgPlayable(st,player):dominoPlayable2(st,player);}
function dominoMove(st,players,turnIdx,move){return st&&st.bergen?dominoBgMove(st,players,turnIdx,move):dominoMove2(st,players,turnIdx,move);}

// One alert per player (Nov 19 2026, Kevin): the first alert from a player (a seat invite or a turn) reaches you; while that player keeps playing, even 25 games, nothing more comes until they've been quiet for an hour.
async function ohanaPlayAlertOk(db,to,from){try{const t=Date.now();const row=await db.prepare("SELECT last_at FROM play_alerts WHERE member_id=? AND from_id=?").bind(to,from).first();await db.prepare("INSERT INTO play_alerts(member_id,from_id,last_at) VALUES(?,?,?) ON CONFLICT(member_id,from_id) DO UPDATE SET last_at=excluded.last_at").bind(to,from,t).run();return !row||row.last_at<t-36e5;}catch(e){console.warn("Ohana play alert check failed",e.message);return true;}}
async function notifyMembers(db,memberIds,payload){if(payload&&payload.type==="invite"&&payload.from>0&&memberIds&&memberIds.length){const send=[];for(const to of memberIds)if(await ohanaPlayAlertOk(db,+to,payload.from))send.push(to);if(!send.length)return;payload={...payload,tag:"ohana-player-"+payload.from};memberIds=send;}return notifyMembers0(db,memberIds,payload);}
